declarations.type:
∀ {T : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space} {q : ℝ → Breakdown.Space → ℝ}
  {F : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsForcedSolutionOn T v q F → ∀ t ∈ Set.Ioo 0 T, ContDiff ℝ (↑⊤) (F t)

∀ {T : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space} {q : ℝ → Breakdown.Space → ℝ}
  {F : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsForcedSolutionOn T v q F → ∀ t ∈ Set.Icc 0 T, ∀ (x : Breakdown.Space), Breakdown.divergenceAt (v t) x = 0

∀ {T : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space} {q : ℝ → Breakdown.Space → ℝ}
  {F : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsForcedSolutionOn T v q F → ∀ t ∈ Set.Ioo 0 T, ∀ (x : Breakdown.Space), Breakdown.divergenceAt (F t) x = 0

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {g : Breakdown.Space → E}
  {c : Breakdown.Space},
  (∀ (y : Breakdown.Space), g (y + c) = g y) → ∀ (x : Breakdown.Space), fderiv ℝ g (x + c) = fderiv ℝ g x

∀ {T : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space} {q : ℝ → Breakdown.Space → ℝ}
  {F : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsForcedSolutionOn T v q F → ContDiffOn ℝ (↑⊤) (fun z => v z.1 z.2) (Set.Icc 0 T ×ˢ Set.univ)

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {K : ℝ → Breakdown.Space → E}
  {z : ℝ × Breakdown.Space},
  ContDiffAt ℝ (↑⊤) (fun q => K q.1 q.2) z → ContDiffAt ℝ (↑⊤) (fun q => fderiv ℝ (K q.1) q.2) z

∀ {T : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space} {q : ℝ → Breakdown.Space → ℝ}
  {F : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsForcedSolutionOn T v q F → ContDiffOn ℝ (↑⊤) (fun z => q z.1 z.2) (Set.Icc 0 T ×ˢ Set.univ)
